#include <vector>
#include <string>

class Solution {
public:
    char kthCharacter(long long k, std::vector<int>& operations) {
        long long idx = k - 1;
        long long shifts = 0;
        for (int i = 0; i < (int)operations.size(); ++i) {
            if ((idx >> i) & 1) {
                shifts += operations[i];
            }
        }
        return 'a' + (shifts % 26);
    }
};

class Solution {
    public char kthCharacter(long k, int[] operations) {
        long idx = k - 1;
        long shifts = 0;
        for (int i = 0; i < operations.length; i++) {
            if (((idx >> i) & 1) == 1) {
                shifts += operations[i];
            }
        }
        return (char) ('a' + (shifts % 26));
    }
}

var kthCharacter = function(k, operations) {
    let idx = BigInt(k) - 1n;
    let shifts = 0n;
    for (let i = 0; i < operations.length; i++) {
        if ((idx >> BigInt(i)) & 1n) {
            shifts += BigInt(operations[i]);
        }
    }
    return String.fromCharCode(97 + Number(shifts % 26n));
};
